import{_ as e,o as a,c as r,a2 as n}from"./chunks/framework.il0noOp3.js";const f=JSON.parse('{"title":"Cloud for Financial Services Well-Architected — enumerated source for the Microsoft Cloud for Financial Services Well-Architected for Industry assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/cloud-for-financial-services-question-set.md","filePath":"frameworks/cloud-for-financial-services-question-set.md"}'),o={name:"frameworks/cloud-for-financial-services-question-set.md"};function d(i,t,s,c,l,h){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="cloud-for-financial-services-well-architected-—-enumerated-source-for-the-microsoft-cloud-for-financial-services-well-architected-for-industry-assessment" tabindex="-1">Cloud for Financial Services Well-Architected — enumerated source for the Microsoft Cloud for Financial Services Well-Architected for Industry assessment <a class="header-anchor" href="#cloud-for-financial-services-well-architected-—-enumerated-source-for-the-microsoft-cloud-for-financial-services-well-architected-for-industry-assessment" aria-label="Permalink to &quot;Cloud for Financial Services Well-Architected — enumerated source for the Microsoft Cloud for Financial Services Well-Architected for Industry assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>mcfs.wellarchitected.yaml</code> reviews a financial services workload against the Well-Architected for Industry guidance and the Microsoft financial services guidance (landing zones, policy, compliance tools, operational resilience). It is Scout&#39;s counterpart to the <a href="https://learn.microsoft.com/en-us/assessments/85444ed4-5423-440a-aae0-a03a70981d6c/" target="_blank" rel="noreferrer">Microsoft Cloud for Financial Services | Well-Architected for Industry</a> assessment, which Microsoft Learn now lists as the Microsoft for Financial Services Assessment. <code>src/assess/rules/mcfs.wellarchitected.yaml</code> is written against this page only, and every rule cites an item number from the tables below. Every item is a <strong>manual</strong> question answered with <code>-AssessmentAnswers</code>.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td>[Microsoft Cloud for Financial Services</td></tr><tr><td>Framework version</td><td>Well-Architected for Industry pillar overviews and Microsoft for Financial Services guidance on Microsoft Learn, current as of the extraction date; no published version number</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>Pages marked <code>fetched</code> in the source list were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25. Pages marked <code>search excerpt</code> were read through <code>microsoft_docs_search</code> excerpts on the same day, not in full. The URL for the product-specific Well-Architected pages (<code>industry/well-architected/financial-services/</code>) returned the What is Microsoft for Financial Services page when fetched, so no assessment-specific design, deployment or monitoring page could be read. No tenant was read.</td></tr></tbody></table><h2 id="product-status" tabindex="-1">Product status <a class="header-anchor" href="#product-status" aria-label="Permalink to &quot;Product status&quot;">​</a></h2><p>Checked against Microsoft Learn on 2026-11-25.</p><ul><li><strong>Renamed, not retired.</strong> Microsoft Cloud for Financial Services is now <strong>Microsoft for Financial Services</strong>. Learn&#39;s Well-Architected for Industry overview lists this same assessment as the &quot;Microsoft for Financial Services Assessment&quot; and describes it as covering configuration and extension scenarios across the reliability, cost, operational excellence, security and performance efficiency pillars. Only archived release-plan pages keep the old product name. Scout keeps the <code>MCFS-</code> prefix and the catalog assessment name.</li><li><strong>Limit of the source.</strong> The product-specific Well-Architected pages did not return content of their own (see the verification method). The items rest on the five pillar overviews and the financial services pages instead, so they are broader and less product-specific than Microsoft&#39;s assessment is likely to be.</li><li><strong>Deprecated components.</strong> Learn lists these as deprecated and not available for deployment: Financial Meeting Prep (2025-10-01, replaced by the LSEG Workspace app in Teams), the financial document analysis skill for agents (2025-08-04, replaced by Azure AI Search and Azure OpenAI), Intelligent appointments (2024-05-22), Collaboration Manager for Loans, the loan tracker and sample loan onboarding portal, and Banking customer intelligence (2023-09-01), and the Dynamics 365 financial services accelerator (2021-07-01). MCFS-OE-05 asks whether any is in use.</li></ul><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>The questions are Scout-derived, not Microsoft&#39;s.</strong> The assessment&#39;s question text is not published, so the items below are Scout&#39;s reading of the guidance listed above. The <code>MCFS-*</code> IDs, and the assignment of an item to a group, are Scout&#39;s own.</p><p><strong>Scout does not read this product&#39;s data yet.</strong> Microsoft for Financial Services is built on Dynamics 365, Power Platform and Azure. Scout reads the Azure part (Resource Graph and ARM) through its other assessments, and one Microsoft Entra policy; it does not read Dataverse, Power Platform or Dynamics 365 data and the collect.json contract in <code>src/collect/Invoke-Collect.ps1</code> holds no Conditional Access data. So every rule is <code>manual: true</code> with <code>query: null</code>: it is exported as a question by <code>Export-ScoutAssessmentQuestion</code>, answered with <code>-AssessmentAnswers</code> (see <a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>), and stays Manual and out of the score until answered. Where the Azure part of the estate bears on an item, run the Azure assessments (for example the landing zone, security and reliability reviews) alongside this one.</p><p>Sources:</p><ul><li>[WAI] <a href="https://learn.microsoft.com/industry/well-architected/overview" target="_blank" rel="noreferrer">Overview of Well-Architected for Industry (lists the Microsoft for Financial Services assessment)</a> -- fetched</li><li>[REL] <a href="https://learn.microsoft.com/industry/well-architected/reliability" target="_blank" rel="noreferrer">Overview of the reliability pillar (Well-Architected for Industry)</a> -- fetched</li><li>[SEC] <a href="https://learn.microsoft.com/industry/well-architected/security" target="_blank" rel="noreferrer">Overview of the security pillar (Well-Architected for Industry)</a> -- fetched</li><li>[COST] <a href="https://learn.microsoft.com/industry/well-architected/cost-optimization" target="_blank" rel="noreferrer">Overview of the cost optimization pillar (Well-Architected for Industry)</a> -- fetched</li><li>[OPE] <a href="https://learn.microsoft.com/industry/well-architected/operation-excellence" target="_blank" rel="noreferrer">Overview of the operational excellence pillar (Well-Architected for Industry)</a> -- fetched</li><li>[PERF] <a href="https://learn.microsoft.com/industry/well-architected/performance-efficiency" target="_blank" rel="noreferrer">Overview of the performance efficiency pillar (Well-Architected for Industry)</a> -- fetched</li><li>[FSI] <a href="https://learn.microsoft.com/industry/financial-services/fsi-overview" target="_blank" rel="noreferrer">What is Microsoft for Financial Services?</a> -- fetched</li><li>[CT] <a href="https://learn.microsoft.com/industry/financial-services/microsoft-compliance-tools" target="_blank" rel="noreferrer">Microsoft compliance tools (financial services)</a> -- fetched</li><li>[RES] <a href="https://learn.microsoft.com/compliance/assurance/assurance-fsi-resilience" target="_blank" rel="noreferrer">Strengthening operational resilience and reducing concentration risk in financial services</a> -- fetched</li><li>[GOVF] <a href="https://learn.microsoft.com/industry/financial-services/infra-governance-fsi" target="_blank" rel="noreferrer">Infrastructure governance (financial services)</a> -- search excerpt</li><li>[AZ] <a href="https://learn.microsoft.com/industry/financial-services/microsoft-azure-fsi" target="_blank" rel="noreferrer">Microsoft Azure for financial services (Payment HSM, confidential computing)</a> -- search excerpt</li><li>[M365F] <a href="https://learn.microsoft.com/industry/financial-services/microsoft-365-fsi" target="_blank" rel="noreferrer">Microsoft 365 for financial services (data residency, double key encryption, customer-managed keys)</a> -- search excerpt</li><li>[ENAB] <a href="https://learn.microsoft.com/industry/financial-services/service-enablement-framework" target="_blank" rel="noreferrer">Cloud service enablement framework for regulated financial institutions</a> -- search excerpt</li><li>[DEPR] <a href="https://learn.microsoft.com/industry/financial-services/fsi-deprecation" target="_blank" rel="noreferrer">Deprecations in Microsoft for Financial Services</a> -- search excerpt</li><li>[PPWA] <a href="https://learn.microsoft.com/power-platform/well-architected/what-is-power-well-architected" target="_blank" rel="noreferrer">What is Power Platform Well-Architected?</a> -- search excerpt</li><li>[DM] <a href="https://learn.microsoft.com/common-data-model/schema/core/industrycommon/financialservices/overview" target="_blank" rel="noreferrer">Overview of Microsoft for Financial Services entities (Common Data Model)</a> -- search excerpt</li></ul><p>Every item is <strong>manual</strong>: it is exported as a question and scored only when answered with <code>-AssessmentAnswers</code> (see <a href="./../assessment/questionnaire-answers.html">Questionnaire Answers</a>).</p><h2 id="the-enumeration-—-40-items-across-7-groups" tabindex="-1">The enumeration — 40 items across 7 groups <a class="header-anchor" href="#the-enumeration-—-40-items-across-7-groups" aria-label="Permalink to &quot;The enumeration — 40 items across 7 groups&quot;">​</a></h2><h3 id="reliability-mcfs-re-—-7-items" tabindex="-1">Reliability (MCFS-RE) — 7 items <a class="header-anchor" href="#reliability-mcfs-re-—-7-items" aria-label="Permalink to &quot;Reliability (MCFS-RE) — 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MCFS-RE-01</td><td>Business-critical services are identified, with recovery objectives and impact tolerances set for each</td><td>Manual</td><td>REL, RES</td></tr><tr><td>MCFS-RE-02</td><td>Workloads are designed for availability: multiple zones, redundancy of network and data, design for failure</td><td>Manual</td><td>REL, RES, AZ</td></tr><tr><td>MCFS-RE-03</td><td>Changes are deployed by automation, with testing and validation, and with safe rollout techniques</td><td>Manual</td><td>REL</td></tr><tr><td>MCFS-RE-04</td><td>Failures are detected, isolated and recovered through monitoring, alerting, and tested disaster recovery and continuity plans</td><td>Manual</td><td>REL, RES</td></tr><tr><td>MCFS-RE-05</td><td>Capacity is planned and workloads scale to demand</td><td>Manual</td><td>REL, FSI</td></tr><tr><td>MCFS-RE-06</td><td>Dependencies on cloud providers and third parties are mapped to critical use cases, and concentration risk is assessed</td><td>Manual</td><td>RES</td></tr><tr><td>MCFS-RE-07</td><td>Exit plans exist for services that support critical or important functions</td><td>Manual</td><td>RES</td></tr></tbody></table><h3 id="security-mcfs-se-—-9-items" tabindex="-1">Security (MCFS-SE) — 9 items <a class="header-anchor" href="#security-mcfs-se-—-9-items" aria-label="Permalink to &quot;Security (MCFS-SE) — 9 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MCFS-SE-01</td><td>Security governance covers monitoring, logging and a tested incident response plan with escalation</td><td>Manual</td><td>SEC</td></tr><tr><td>MCFS-SE-02</td><td>Identity and access follow least privilege, with multifactor authentication and strong identity management</td><td>Manual -- Conditional Access policies are not in collect.json</td><td>SEC, FSI</td></tr><tr><td>MCFS-SE-03</td><td>Customer security responsibilities for each service type (IaaS, PaaS, SaaS) are written down and owned</td><td>Manual</td><td>WAI, SEC</td></tr><tr><td>MCFS-SE-04</td><td>Network, host and application layers have security controls that limit the effect of an attack</td><td>Manual</td><td>SEC, AZ</td></tr><tr><td>MCFS-SE-05</td><td>Data is classified, encrypted at rest and in transit, and retained by policy; the strongest controls are used for the most sensitive data</td><td>Manual</td><td>SEC, FSI, AZ, M365F</td></tr><tr><td>MCFS-SE-06</td><td>Applications and AI services built on the platform follow secure development and AI governance practices</td><td>Manual</td><td>SEC, FSI</td></tr><tr><td>MCFS-SE-07</td><td>Defender for Cloud and Purview Compliance Manager are used to find and track security and compliance gaps</td><td>Manual</td><td>CT</td></tr><tr><td>MCFS-SE-08</td><td>Payment cryptography uses a certified payment HSM where payment transactions are processed (if applicable)</td><td>Manual</td><td>AZ</td></tr><tr><td>MCFS-SE-09</td><td>Data residency and sovereignty needs are met with the right residency, key and cloud options</td><td>Manual</td><td>FSI, M365F</td></tr></tbody></table><h3 id="cost-optimization-mcfs-co-—-4-items" tabindex="-1">Cost optimization (MCFS-CO) — 4 items <a class="header-anchor" href="#cost-optimization-mcfs-co-—-4-items" aria-label="Permalink to &quot;Cost optimization (MCFS-CO) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MCFS-CO-01</td><td>Services use the right pricing model and size, with reservations or savings plans where use is steady</td><td>Manual</td><td>COST</td></tr><tr><td>MCFS-CO-02</td><td>Supply is matched to demand through autoscaling and usage-based options</td><td>Manual</td><td>COST</td></tr><tr><td>MCFS-CO-03</td><td>Idle and under-used resources are found and removed or right-sized</td><td>Manual</td><td>COST</td></tr><tr><td>MCFS-CO-04</td><td>Costs are managed over time: budgets, tagging and cost allocation, plus licence and Dataverse storage management</td><td>Manual</td><td>COST</td></tr></tbody></table><h3 id="operational-excellence-mcfs-oe-—-5-items" tabindex="-1">Operational excellence (MCFS-OE) — 5 items <a class="header-anchor" href="#operational-excellence-mcfs-oe-—-5-items" aria-label="Permalink to &quot;Operational excellence (MCFS-OE) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MCFS-OE-01</td><td>Azure, Power Platform and Dynamics 365 components are monitored together, with analytics exported for review</td><td>Manual</td><td>OPE</td></tr><tr><td>MCFS-OE-02</td><td>Routine operations are automated to reduce manual effort and error</td><td>Manual</td><td>OPE</td></tr><tr><td>MCFS-OE-03</td><td>Release engineering uses separate environments, solution lifecycle management and quality checks</td><td>Manual</td><td>OPE, PPWA</td></tr><tr><td>MCFS-OE-04</td><td>Support processes, runbooks and incident handling cover the whole solution</td><td>Manual</td><td>OPE, WAI</td></tr><tr><td>MCFS-OE-05</td><td>No deprecated Microsoft for Financial Services component is deployed or planned</td><td>Manual</td><td>DEPR</td></tr></tbody></table><h3 id="performance-efficiency-mcfs-pe-—-4-items" tabindex="-1">Performance efficiency (MCFS-PE) — 4 items <a class="header-anchor" href="#performance-efficiency-mcfs-pe-—-4-items" aria-label="Permalink to &quot;Performance efficiency (MCFS-PE) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MCFS-PE-01</td><td>Resource types and architecture were chosen for the performance each workload needs</td><td>Manual</td><td>PERF</td></tr><tr><td>MCFS-PE-02</td><td>Workloads scale up and down, and caching and network optimisation are used where latency matters</td><td>Manual</td><td>PERF, RES</td></tr><tr><td>MCFS-PE-03</td><td>Performance is logged and monitored so problems are found before users report them</td><td>Manual</td><td>PERF</td></tr><tr><td>MCFS-PE-04</td><td>Power Platform and Dataverse service limits are designed for</td><td>Manual</td><td>PERF, PPWA</td></tr></tbody></table><h3 id="configuration-and-extension-mcfs-ce-—-5-items" tabindex="-1">Configuration and extension (MCFS-CE) — 5 items <a class="header-anchor" href="#configuration-and-extension-mcfs-ce-—-5-items" aria-label="Permalink to &quot;Configuration and extension (MCFS-CE) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MCFS-CE-01</td><td>The standard financial services data model and out-of-the-box configuration are used before anything is customised</td><td>Manual</td><td>DM, FSI</td></tr><tr><td>MCFS-CE-02</td><td>Extensions use supported techniques and add to the standard solution without changing its managed components</td><td>Manual</td><td>PPWA, WAI</td></tr><tr><td>MCFS-CE-03</td><td>Data model extensions are documented, owned and reviewed for upgrade impact</td><td>Manual</td><td>DM, PPWA</td></tr><tr><td>MCFS-CE-04</td><td>Integrations with core banking and other systems are designed, documented and tested for failure</td><td>Manual</td><td>FSI, REL</td></tr><tr><td>MCFS-CE-05</td><td>Copilots and AI features added through extension are scoped, secured and governed</td><td>Manual</td><td>FSI, SEC</td></tr></tbody></table><h3 id="governance-compliance-and-operational-resilience-mcfs-gv-—-6-items" tabindex="-1">Governance, compliance and operational resilience (MCFS-GV) — 6 items <a class="header-anchor" href="#governance-compliance-and-operational-resilience-mcfs-gv-—-6-items" aria-label="Permalink to &quot;Governance, compliance and operational resilience (MCFS-GV) — 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>MCFS-GV-01</td><td>An Azure landing zone, with platform and application landing zones, hosts the Azure workloads</td><td>Manual</td><td>FSI, GOVF</td></tr><tr><td>MCFS-GV-02</td><td>Azure Policy initiatives enforce the organisation and regulatory controls, with a compliance view</td><td>Manual</td><td>GOVF, FSI</td></tr><tr><td>MCFS-GV-03</td><td>Applicable financial services regulations are identified for each jurisdiction and mapped to controls</td><td>Manual</td><td>RES, CT</td></tr><tr><td>MCFS-GV-04</td><td>Cloud risk governance, risk tolerance and risk appetite are updated at least annually</td><td>Manual</td><td>RES</td></tr><tr><td>MCFS-GV-05</td><td>New cloud services pass a service enablement review before production use</td><td>Manual</td><td>ENAB</td></tr><tr><td>MCFS-GV-06</td><td>Audit evidence is available: Microsoft attestations and the Service Trust Portal are used for the Microsoft-responsible controls</td><td>Manual</td><td>FSI, CT</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Items</th><th>Automated</th><th>Manual</th></tr></thead><tbody><tr><td>Reliability</td><td>7</td><td>0</td><td>7</td></tr><tr><td>Security</td><td>9</td><td>0</td><td>9</td></tr><tr><td>Cost optimization</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Operational excellence</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Performance efficiency</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Configuration and extension</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Governance, compliance and operational resilience</td><td>6</td><td>0</td><td>6</td></tr><tr><td><strong>Total</strong></td><td><strong>40</strong></td><td><strong>0</strong></td><td><strong>40</strong></td></tr></tbody></table><h2 id="what-an-automated-version-would-need" tabindex="-1">What an automated version would need <a class="header-anchor" href="#what-an-automated-version-would-need" aria-label="Permalink to &quot;What an automated version would need&quot;">​</a></h2><p>Everything below needs read-only access to the environment, a new collect section, and a gate on each rule so an environment that was not read reports Not assessed instead of Pass.</p><table tabindex="0"><thead><tr><th>Items</th><th>What would be read</th><th>Interface and permission</th></tr></thead><tbody><tr><td>MCFS-GV-01, GV-02, RE-02, SE-04, SE-07, CO-04</td><td>Landing zone, policy assignments, zones, network controls, Defender plans, budgets and tags on the Azure side</td><td>Azure Resource Graph and ARM, which Scout already reads (see the Azure rule files)</td></tr><tr><td>MCFS-SE-02</td><td>Conditional Access and multifactor policy</td><td>Microsoft Graph v1.0 <code>GET /identity/conditionalAccess/policies</code>; <code>Policy.Read.All</code></td></tr><tr><td>MCFS-OE-03, OE-05, CE-02, CE-03</td><td>Installed solutions, managed or unmanaged state, and which deprecated components are present</td><td>Dataverse Web API tables <code>solution</code> and <code>solutioncomponent</code> (not researched in this pass)</td></tr><tr><td>MCFS-OE-01</td><td>Dataverse auditing and Application Insights export</td><td>Dataverse Web API <code>organizations</code> columns <code>isauditenabled</code>, <code>auditretentionperiodv2</code>; Power Platform admin center data export</td></tr><tr><td>MCFS-SE-07</td><td>Compliance Manager assessments and improvement actions</td><td>No read API for Compliance Manager was found on Learn in this pass</td></tr></tbody></table><p>Items about risk governance, exit plans, regulation mapping, operating model and design intent (most of MCFS-RE, MCFS-GV and MCFS-CE) have no API behind them and stay manual in any version.</p>',35)])])}const m=e(o,[["render",d]]);export{f as __pageData,m as default};
